    cat("\n\n"); 
    Rs = summary(x)[c("r.squared", "adj.r.squared")] 
    zz = c(Rs$r.squared,Rs$adj.r.squared); 
    names(zz) = c("r.squared","adj.r.squared") 
    print.default((format(zz,digits=digits) ),print.gap = 2,quote=FALSE) 
  } 
  else cat("No coefficients\n") 
  cat("\n") 
  invisible(x) 
} 

